Script:
// Matrix rain - glowing green glyphs cascade down the panel, leaving long
// fading trails behind each falling head.
@scene fps=30 bg=#000300 trail=0.85 size=32x48

emit drops
  rate    = ${density} per 0.04..0.09s
  origin  = x:rand y:top
  vel     = dir:down speed:${speed}
  gravity = down 2
  color   = pick(#00ff66,#00ff99,#33ffaa,#ccffdd)
  life    = ${fade}s
